    .equ VDP_DATA,      0x00C00000
    .equ VDP_CTRL,      0x00C00004
    .equ SPRITE_TILE_BASE, 1024
    .equ ARCADE_ROM_BASE, 0x00000200
    .equ PC090OJ_HW_BASE, 0x00D00000
    /* Active mirrored HW window tracks the configured record count so that when
     * PC090OJ_MIRROR_RECORDS < 256 the address-based mirror writers reject
     * out-of-range records instead of overflowing the smaller mirror array. */
    .equ PC090OJ_HW_ACTIVE_END, (PC090OJ_HW_BASE + PC090OJ_MIRROR_BYTES)
    /* Arcade A5 work-RAM base.  Absolute arcade work-RAM pointers (0x0010Cxxx)
     * map to Genesis WRAM as a5 + (pointer - ARCADE_WORKRAM_A5_BASE); the Genesis
     * a5 (0x00FF0000) corresponds to this arcade base (arcade 0x0010C000 ->
     * Genesis 0x00FF0000, e.g. the ranking table names at 0x00FF0157). */
    .equ ARCADE_WORKRAM_A5_BASE, 0x0010C000
    /* Arcade 0x59F5E clears 8 PC090OJ records starting at HW 0x00D00048
     * (= PC090OJ_HW_BASE + record 9), i.e. records 9..16.  It never touches the
     * HIGH SCORE label records 4..8.  (Build 0149 fix: the translation cleared
     * records 0..7, wiping label records 4..7 on coin insertion -> only "RE"
     * remained above 273100.) */
    .equ HOOK_59F5E_CLEAR_FIRST_RECORD, 9   /* (0x00D00048 - PC090OJ_HW_BASE) / 8 */
    .equ HOOK_59F5E_CLEAR_RECORD_COUNT, 8
    .equ PC090OJ_BLOCK2C8_BASE_RECORD, 140
    .equ PC090OJ_BLOCK2C8_APPLIED_RECORDS, (8 * 10 + 19)
    .equ PC090OJ_BLOCK2C8_SCRATCH_RECORDS, 100
    .equ PC090OJ_BLOCK2C8_SCRATCH_BYTES, (PC090OJ_BLOCK2C8_SCRATCH_RECORDS * 8)
    .if PC090OJ_BLOCK2C8_APPLIED_RECORDS > PC090OJ_BLOCK2C8_SCRATCH_RECORDS
    .error "block A5+0x2C8 scratch too small"
    .endif
    .if (PC090OJ_BLOCK2C8_BASE_RECORD + PC090OJ_BLOCK2C8_APPLIED_RECORDS - 1) != 238
    .error "block A5+0x2C8 record span must end at record 238"
    .endif

    /* ------------------------------------------------------------------ *
     * Build 0147: PC090OJ viewport coordinate + opaque-clip constants.   *
     * Named so sprite/background alignment is easy to read and to tune   *
     * during later emulator, gameplay, and real-CRT testing.             *
     * ------------------------------------------------------------------ */
    /* 16x16 sprite cell geometry. */
    .equ PC090OJ_PATTERN_WIDTH,   16
    .equ PC090OJ_PATTERN_HEIGHT,  16
    .equ PC090OJ_PATTERN_MAX_ROW, 15    /* PC090OJ_PATTERN_HEIGHT - 1 */
    .equ PC090OJ_PATTERN_MAX_COL, 15    /* PC090OJ_PATTERN_WIDTH  - 1 */
    /* Arcade PC090OJ non-flipped coordinate inversion (MAME taito/pc090oj.cpp:
     * x = 320 - x - 16, y = 256 - y - 16 when the flip-screen ctrl bit is clear). */
    .equ PC090OJ_FLIP_X_TERM, 304       /* 320 - PC090OJ_PATTERN_WIDTH  */
    .equ PC090OJ_FLIP_Y_TERM, 240       /* 256 - PC090OJ_PATTERN_HEIGHT */
    /* Arcade -> Genesis display-origin alignment.  The background plane applies
     * VDP_DISPLAY_ORIGIN_Y_BIAS(=8) / _X_BIAS(=16) in vdp_comm.s so the arcade
     * visible-area origin (raster Y=8, per rastan.cpp set_visarea 8..247) maps to
     * Genesis display line 0.  Sprites use the SAME origin so sprite/background
     * stay vertically aligned; this also places the arcade top margin above the
     * Genesis viewport, where its records clip out naturally.  Configurable. */
    .equ PC090OJ_TO_GENESIS_Y_OFFSET, -8   /* = -VDP_DISPLAY_ORIGIN_Y_BIAS */
    .equ PC090OJ_TO_GENESIS_X_OFFSET,  0   /* frontend X already aligned; tune later */
    /* Effective sprite clip rectangle = intersection of the arcade visible area
     * (raster 8..247 -> Genesis 0..239 after the Y origin) and the Genesis output
     * viewport (0..223, 0..319).  The Genesis bounds bind; ends are exclusive. */
    .equ GENESIS_VIEWPORT_LEFT,   0
    .equ GENESIS_VIEWPORT_RIGHT,  320
    .equ GENESIS_VIEWPORT_TOP,    0
    .equ GENESIS_VIEWPORT_BOTTOM, 224
    /* Genesis SAT coordinate biases (SAT value = screen coord + bias). */
    .equ PC090OJ_SAT_Y_BIAS, 0x80
    .equ PC090OJ_SAT_X_BIAS, 0x80

/* ------------------------------------------------------------------------- */
/* Internal helpers                                                          */
/* ------------------------------------------------------------------------- */

/* d0=PC090OJ record index.  Candidate state is helper-derived; mirror remains truth. */

/* d2=byte offset inside the active 0x800-byte PC090OJ mirror. */

/* d6=PC090OJ record index.  Clear only after full-record code-zero decode. */

/* Legacy producer bridge (Build 0142): the unconverted per-site hooks publish
 * their arcade sprite record into the mirror and set the per-record candidate.
 * The staged SAT is no longer written here; it is rebuilt from the mirror by
 * .Lpc090oj_sync_record_from_mirror during VBlank (dirty candidates) so a single
 * retained renderer owns the SAT.  d0=record index; d1=word0,d2=Y,d3=code,d4=X.
 * Preserves d0-d4/d7 and a1..a6 for the calling producer loops.
 */
.Lpc090oj_emit_slot:
    movem.l %d5/%d6/%a0, -(%sp)
    cmpi.w  #256, %d0
    bhs.s   .Lpc090oj_emit_slot_oob
    move.w  %d0, %d6
    lsl.w   #3, %d6
    lea     pc090oj_object_ram, %a0
    adda.w  %d6, %a0
    move.w  %d1, (%a0)
    move.w  %d2, 2(%a0)
    move.w  %d3, 4(%a0)
    move.w  %d4, 6(%a0)
    addq.w  #1, pc090oj_producer_write_count
    movem.l (%sp)+, %d5/%d6/%a0
    rts
.Lpc090oj_emit_slot_oob:
    addq.w  #1, pc090oj_producer_oob_count
    movem.l (%sp)+, %d5/%d6/%a0
    rts


/* d0=slot clears slot */
.Lpc090oj_clear_slot:
    moveq   #0, %d1
    move.w  #0x0180, %d2
    moveq   #0, %d3
    moveq   #0, %d4
    moveq   #0, %d5
    moveq   #0, %d6
    moveq   #0, %d7
    bsr     .Lpc090oj_emit_slot
    rts

/* A1=PC090OJ HW address, D0=word value.  Writes only the active 0x800-byte mirror. */
.Lpc090oj_mirror_write_word_a1_d0:
    move.l  %a2, -(%sp)
    move.l  %a1, %d2
    cmpi.l  #PC090OJ_HW_BASE, %d2
    blo.s   .Lpc090oj_mirror_word_oob
    cmpi.l  #PC090OJ_HW_ACTIVE_END, %d2
    bhs.s   .Lpc090oj_mirror_word_oob
    subi.l  #PC090OJ_HW_BASE, %d2
    lea     pc090oj_object_ram, %a2
    adda.l  %d2, %a2
    move.w  %d0, (%a2)
    addq.w  #1, pc090oj_producer_write_count
    move.l  (%sp)+, %a2
    rts
.Lpc090oj_mirror_word_oob:
    addq.w  #1, pc090oj_producer_oob_count
    move.l  (%sp)+, %a2
    rts

/* A1=PC090OJ HW address, D0=byte value.  Used for 0x3B802 byte stores. */
.Lpc090oj_mirror_write_byte_a1_d0:
    move.l  %a2, -(%sp)
    move.l  %a1, %d2
    cmpi.l  #PC090OJ_HW_BASE, %d2
    blo.s   .Lpc090oj_mirror_byte_oob
    cmpi.l  #PC090OJ_HW_ACTIVE_END, %d2
    bhs.s   .Lpc090oj_mirror_byte_oob
    subi.l  #PC090OJ_HW_BASE, %d2
    lea     pc090oj_object_ram, %a2
    adda.l  %d2, %a2
    move.b  %d0, (%a2)
    addq.w  #1, pc090oj_producer_write_count
    move.l  (%sp)+, %a2
    rts
.Lpc090oj_mirror_byte_oob:
    addq.w  #1, pc090oj_producer_oob_count
    move.l  (%sp)+, %a2
    rts

/* Converted semantic family (Build 0142): the complete 22-object work-RAM block
 * shared by arcade 0x041DAE / 0x041F5E / 0x045DFA.  Block A = 18 records at
 * A5+0x11B2, block B = 4 records at A5+0x0170; tuple = {word0, Y, code, X}.
 * Each record is written once into the mirror (exact arcade store), then
 * synchronized directly from the mirror and its superseded candidate cleared.
 * It does NOT set a candidate; later unconverted writes to the same record
 * re-set the candidate and VBlank re-syncs it (§9-E.2/§9-E.3).
 */
/* 0x041F5E path (KF-044 companion): the original arcade routine copies
 *   lea 0x11B2(a5),a0 ; moveq #18 ; lea 0xD003C0,a1   (0xD003C0/8 = record 120)
 *   lea 0x0170(a5),a0 ; moveq #4  ; lea 0xD002E0,a1   (0xD002E0/8 = record 92)
 * so block A -> records 120..137 and block B -> records 92..95.  The previous
 * translation collapsed both blocks to records 0..17 / 18..21, so the player
 * PC090OJ cluster (which the represent engine reads from the arcade-correct
 * records) was never populated.  Restore the arcade destination records. */
pc090oj_workram_block_sprites_41f5e:
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    move.w  #120, %d5                    /* block A base record (0xD003C0/8) */
    move.w  #92, %d7                     /* block B base record (0xD002E0/8) */
    bra.s   .Lwbs_run

/* Default path: arcade 0x045DFA hook and any legacy caller keep the prior
 * mapping (block A -> 0..17, block B -> 18..21).  Arcade 0x045DFA is a distinct
 * routine (sources A5+0x5C8/0x748/0x8C8, dest records 140/46/96 via 0x3D054),
 * so its true destination is out of this fix's proven scope -- unchanged. */
pc090oj_workram_block_sprites:
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    move.w  #0, %d5
    move.w  #18, %d7
.Lwbs_run:
    lea     0x11B2(%a5), %a0
    move.w  %d5, %d0                     /* d0 = block A base record */
    move.w  %d5, %d6
    addi.w  #18, %d6                     /* d6 = block A end (exclusive) */
.Lwbs_block_a:
    move.w  (%a0), %d1
    move.w  2(%a0), %d2
    move.w  4(%a0), %d3
    move.w  6(%a0), %d4
    bsr     .Lpc090oj_family_apply_record
    adda.w  #8, %a0
    addq.w  #1, %d0
    cmp.w   %d6, %d0
    blo.s   .Lwbs_block_a

    lea     0x0170(%a5), %a0
    move.w  %d7, %d0                     /* d0 = block B base record */
    move.w  %d7, %d6
    addi.w  #4, %d6                      /* d6 = block B end (exclusive) */
.Lwbs_block_b:
    move.w  (%a0), %d1
    move.w  2(%a0), %d2
    move.w  4(%a0), %d3
    move.w  6(%a0), %d4
    bsr     .Lpc090oj_family_apply_record
    adda.w  #8, %a0
    addq.w  #1, %d0
    cmp.w   %d6, %d0
    blo.s   .Lwbs_block_b
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

/* d0=record, d1=word0, d2=Y, d3=code, d4=X.  Write the mirror once, then sync
 * from the mirror and clear the superseded candidate, inside a VINT-masked
 * critical section so a VBlank commit never observes a half-applied structural
 * change (§9-C interrupt safety).
 */
/* d0=record, d1..d4 = tuple.  N1: plain object-table write (no candidates,
 * no compare, no interrupt masking -- matches arcade object-RAM semantics). */
.Lpc090oj_family_apply_record:
    movem.l %d5-%d6/%a0, -(%sp)
    cmpi.w  #256, %d0
    bhs.s   .Lpc090oj_far_oob
    move.w  %d0, %d6
    lsl.w   #3, %d6
    lea     pc090oj_object_ram, %a0
    adda.w  %d6, %a0
    move.w  %d1, (%a0)
    move.w  %d2, 2(%a0)
    move.w  %d3, 4(%a0)
    move.w  %d4, 6(%a0)
    addq.w  #1, pc090oj_producer_write_count
    movem.l (%sp)+, %d5-%d6/%a0
    rts
.Lpc090oj_far_oob:
    addq.w  #1, pc090oj_producer_oob_count
    movem.l (%sp)+, %d5-%d6/%a0
    rts


/* ------------------------------------------------------------------------- */
/* 17 helpers                                                                */
/* ------------------------------------------------------------------------- */

/* Build 0146 faithful translation of arcade 0x03B902.
 * Arcade body: lea 0xD00088,%a1 (records 17..21); tst.w %d1; bne fill.
 *   clear path (d1==0): lea 0x3B984,%a0; moveq #5,%d1; bsr 0x3B930   -> copy the
 *     5-record table at arcade 0x3B984 (Genesis 0x3BB84) into records 17..21.
 *   fill path  (d1!=0): move.b %d1,2(%a1); addq.l #8,%a1  x5  -> write the byte
 *     d1 to the Y-high byte (offset 2) of records 17..21 only.
 * The prior Build 0142-era body wrote full descriptors to records 0..4, which
 * clobbered record 4 (the HIGH SCORE "GH" glyph) that the arcade never touches.
 * Registers are fully preserved (movem), matching the prior helper's contract.
 */
genesistan_pc090oj_hook_target_3b902:
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    tst.w   %d1
    bne.s   .Lhook_3b902_fill
    /* clear path: table copy into records 17..21 via the faithful 0x3B930 helper */
    lea     0x00D00088, %a1
    lea     0x0003BB84, %a0                 /* arcade 0x3B984 table, +0x200 */
    moveq   #5, %d1
    bsr     genesistan_pc090oj_hook_target_3b930
    bra.s   .Lhook_3b902_done
.Lhook_3b902_fill:
    /* fill path: write byte d1 to the Y-high byte (offset 2) of records 17..21 */
    lea     0x00D0008A, %a1                 /* 0xD00088 + 2 (record 17 Y-high) */
    moveq   #5, %d5
.Lhook_3b902_fill_loop:
    move.w  %d1, %d0
    bsr     .Lpc090oj_mirror_write_byte_a1_d0
    adda.l  #8, %a1
    subq.w  #1, %d5
    bne.s   .Lhook_3b902_fill_loop
.Lhook_3b902_done:
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

genesistan_pc090oj_hook_target_3b926:
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    moveq   #5, %d0
.Lhook_3b926_loop:
    bsr     .Lpc090oj_clear_slot
    addq.w  #1, %d0
    cmpi.w  #14, %d0
    blo.s   .Lhook_3b926_loop
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

genesistan_pc090oj_hook_target_3b930:
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    move.w  %d1, %d6
.Lhook_3b930_loop:
    tst.w   %d6
    beq.s   .Lhook_3b930_done

    moveq   #0, %d0                  /* word0 = 0 */
    bsr     .Lpc090oj_mirror_write_word_a1_d0
    addq.l  #2, %a1

    moveq   #0, %d0                  /* word1 = zero-extended Y byte */
    move.b  (%a0)+, %d0
    bsr     .Lpc090oj_mirror_write_word_a1_d0
    addq.l  #2, %a1

    moveq   #0, %d0                  /* word2 = zero-extended code byte */
    move.b  (%a0)+, %d0
    bsr     .Lpc090oj_mirror_write_word_a1_d0
    addq.l  #2, %a1

    move.w  (%a0)+, %d7              /* word3 = transformed X word */
    jsr     (0x0005B712).l
    move.w  %d7, %d0
    bsr     .Lpc090oj_mirror_write_word_a1_d0
    addq.l  #2, %a1

    subq.w  #1, %d6
    bra.s   .Lhook_3b930_loop
.Lhook_3b930_done:
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

/* Build 0192: hook_target_41dae / hook_target_45dfa replace arcade routines
 * 0x041DAE / 0x045DFA, which do NOT copy A5+0x11B2 (they copy A5+0x508 / A5+0x5C8
 * to records 57/96/140/46 via 0x3D054).  The current Genesis default helper
 * instead copies the PLAYER block A5+0x11B2 -> records 0..17 (and A5+0x0170 ->
 * 18..21), which are exact duplicates of what hook_target_41f5e already stages to
 * the arcade-canonical records 120..137 / 92..95.  In Stage 1 gameplay the arcade
 * records 0..17 are empty, so this low copy is a proven Genesis-only spurious
 * duplicate that draws Rastan twice and wastes ~half the SAT budget.  Suppress it
 * in gameplay only (scene 1); other scenes keep the existing behavior since the
 * low copy has not been proven spurious there. */
genesistan_pc090oj_hook_target_41dae:
    cmpi.b  #PC090OJ_SCENE_GAMEPLAY_ID, genesistan_current_scene_id
    beq.s   .Lhook_41dae_gameplay_record46
    bsr     pc090oj_workram_block_sprites
    rts
.Lhook_41dae_gameplay_record46:
    bsr     pc090oj_stage_block2c8
    bsr     .Lpc090oj_stage_record46_validated
    bsr     pc090oj_native_emit_pass    /* N1: last gameplay producer -> emit */
    rts

genesistan_pc090oj_hook_target_41f5e:
    bsr     pc090oj_workram_block_sprites_41f5e
    rts

genesistan_pc090oj_hook_target_45dfa:
    cmpi.b  #PC090OJ_SCENE_GAMEPLAY_ID, genesistan_current_scene_id
    beq.s   .Lhook_45dfa_skip
    bsr     pc090oj_workram_block_sprites
.Lhook_45dfa_skip:
    rts

/* Build 0204 / OPEN-017: faithfully re-enable the first gameplay enemy block
 * only.  Arcade 0x41E76..0x41EB4 walks A5+0x748 for 11 entries, destination
 * record 46, and calls 0x3D054 with d2=1 after loading d0/d6/d7 from the actor.
 * Keep the Build 0203 safety gate (active, nonzero code, a4+0x36 clear), call
 * the relocated engine into an 8-byte scratch record, and flush only nonzero
 * output tuples into the normal mirror/candidate path. */
.Lpc090oj_stage_record46_validated:
    movem.l %d0-%d7/%a0-%a6, -(%sp)

    lea     0x0748(%a5), %a4
    move.w  #46, .Lrecord46_rec         /* current destination record */
    move.w  #10, .Lrecord46_count       /* 11 actors */

.Lrecord46_loop:
    tst.b   0(%a4)
    beq.s   .Lrecord46_next
    tst.b   1(%a4)
    beq.s   .Lrecord46_next
    tst.b   0x36(%a4)
    bne.s   .Lrecord46_next

    lea     .Lrecord46_scratch, %a1
    clr.l   (%a1)
    clr.l   4(%a1)

    move.b  1(%a4), %d0
    move.b  32(%a4), %d6
    move.b  2(%a4), %d7
    moveq   #1, %d2
    jsr     0x0003D254

    lea     .Lrecord46_scratch, %a0
    move.w  4(%a0), %d3                 /* code word */
    beq.s   .Lrecord46_next             /* never flush code-0 scratch output */
    move.w  (%a0), %d1
    move.w  2(%a0), %d2
    move.w  6(%a0), %d4
    move.w  .Lrecord46_rec, %d0
    bsr     .Lpc090oj_family_apply_record

.Lrecord46_next:
