    rts

/* N1: block A5+0x2C8 -> object-table rows 140..238 DIRECTLY (arcade 0x41E22
 * semantics: d2=10, 19 for entry 8; engine writes exactly d2 rows via (A1)+).
 * KF-067 -8 vertical correction applied to the rows each engine call emits.
 * Deferred-special (a4@(3)!=0) and code-zero entries preserve their rows. */
pc090oj_stage_block2c8:
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    lea     pc090oj_object_ram + (PC090OJ_BLOCK2C8_BASE_RECORD * 8), %a1
    lea     0x02C8(%a5), %a4
    moveq   #0, %d5
.Lb2c8_entry:
    moveq   #10, %d2
    cmpi.w  #8, %d5
    bne.s   .Lb2c8_d2ok
    moveq   #19, %d2
.Lb2c8_d2ok:
    tst.b   0(%a4)
    beq.s   .Lb2c8_blank
    tst.b   5(%a4)
    beq.s   .Lb2c8_blank
    tst.b   3(%a4)
    bne.s   .Lb2c8_skip
    tst.b   1(%a4)
    beq.s   .Lb2c8_skip
    move.b  1(%a4), %d0
    move.b  32(%a4), %d6
    move.b  2(%a4), %d7
    move.w  %d2, -(%sp)                 /* engine clobbers d0-d7 (KF-067) */
    jsr     0x0003D254
    move.w  (%sp)+, %d0
    subq.w  #1, %d0
    movea.l %a1, %a0
.Lb2c8_yfix:
    suba.w  #8, %a0
    move.w  2(%a0), %d1
    move.w  %d1, %d4
    andi.w  #0x01FF, %d1
    subq.w  #8, %d1
    andi.w  #0x01FF, %d1
    andi.w  #0xFE00, %d4
    or.w    %d4, %d1
    move.w  %d1, 2(%a0)
    dbra    %d0, .Lb2c8_yfix
    bra.s   .Lb2c8_next
.Lb2c8_blank:
    move.w  %d2, %d0
    subq.w  #1, %d0
.Lb2c8_blankloop:
    move.w  #0x0180, 2(%a1)
    adda.w  #8, %a1
    dbra    %d0, .Lb2c8_blankloop
    bra.s   .Lb2c8_next
.Lb2c8_skip:
    move.w  %d2, %d0
    lsl.w   #3, %d0
    adda.w  %d0, %a1
.Lb2c8_next:
    adda.w  #64, %a4
    addq.w  #1, %d5
    cmpi.w  #9, %d5
    blo     .Lb2c8_entry
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts


