genesistan_pc090oj_hook_score_digit_3b802:
    movem.l %d0-%d7/%a0-%a6, -(%sp)

    /* Preserve arcade structure at 0x3B802: record = 10 bytes at 0x3B87E+mode*10 */
    clr.l   %d5
    movea.l %d5, %a6                 /* leading-zero state */

    mulu.w  #10, %d0
    lea     .Lhook_3b802_record_table, %a0
