    move.l  %a3, %d2
    tst.w   %d2
    beq     .Lhook_3b802_done

    btst    #0, %d2
    beq.s   .Lhook_3b802_even_nibble

    moveq   #0, %d1
    move.b  (%a2), %d1
    andi.w  #0x000F, %d1
    bsr     .Lhook_3b802_visflag
    addi.w  #0x002A, %d1
    subq.l  #1, %a2
    bra.s   .Lhook_3b802_emit

