    /* snapshot registers (d0-d7,a0-a6 = 15 longs) */
    lea     audit_guard_register_snapshot, %a1
    moveq   #(15 - 1), %d0
.Lag_snap:
    move.l  (%sp,%d0.w*4), %d1
    move.l  %d1, (%a1)+
    dbra    %d0, .Lag_snap

    move.w  0x00C00008, audit_guard_vcount
    move.w  #0x510E, audit_guard_fired_flag

.Lag_halt_loop:
    move.b  audit_guard_heartbeat, %d0
    addq.b  #1, %d0
    move.b  %d0, audit_guard_heartbeat
    bra     .Lag_halt_loop

/* ------------------------------------------------------------------------- */
/* VBlank sprite prepare / commit split                                      */

/* ========================================================================= */
/* N1 native sprite pipeline (Build 0219): object table -> shadow SAT.       */
/*                                                                           */
/* The 256-row object table (pc090oj_object_ram) is the arcade program's own */
/* persistent slot-addressed sprite store: incremental producers (score,     */
/* status, decay, copy hooks) update rows in place exactly as arcade code    */
/* updated PC090OJ RAM.  Once per frame ONE ascending pass emits final       */
/* Genesis SAT entries into a double-buffered shadow SAT.  Ascending row     */
/* order = PC090OJ paint priority (MAME pc090oj draws descending, so record  */
/* 0 lands on top; Genesis link order gives the same result).  Retirement is */
/* implicit: rows the producers cleared/blanked simply emit nothing.         */
/* No mirror shadow, no candidates, no representation/eviction engine, no   */
/* record->slot map, no VBlank record scans in gameplay (the pass runs at    */
/* the end of the arcade's own sprite dispatcher; frontend scenes fall back  */
/* to a VBlank pass).  Residency is code-keyed, 64 sets x 2 ways over 128    */
/* VRAM cells (tiles 1024..1535), so SAT position changes never re-upload.  */
/* ========================================================================= */
    .equ NATIVE_SAT_MAX, 80
    .equ NATIVE_CELLS, 128

/* d1=word0, d7=colbank -> d0 = Genesis palette line (Build 0210 semantics). */
.Lnative_palsel:
    movem.l %d1-%d3, -(%sp)
    move.w  %d1, %d0
    andi.w  #0x000F, %d0
    or.w    %d7, %d0
    cmpi.w  #0x0030, %d0
    bne.s   .Lnp_not48
    moveq   #2, %d0
    bra.s   .Lnp_done
.Lnp_not48:
    cmpi.w  #0x0033, %d0
    bne.s   .Lnp_general
    moveq   #3, %d0
    bra.s   .Lnp_done
.Lnp_general:
.if RASTAN_GAMEPLAY_HUD_SPRITES != 1
    move.w  %d0, %d2                 /* d2 = effective bank */
    moveq   #0, %d0
    move.b  genesistan_current_scene_id, %d0
    moveq   #PROUTE_OWNER_PC090OJ_ID, %d1
    bsr     palette_route_lookup     /* d0 = line or -1; clobbers d0/d3/a0 */
    tst.l   %d0
    bpl.s   .Lnp_done
    movem.l (%sp), %d1-%d3           /* reload live regs, no pop */
    move.w  %d1, %d0
    andi.w  #0x000F, %d0
    or.w    %d7, %d0
.endif
    lsr.w   #4, %d0
    andi.w  #0x0003, %d0
.Lnp_done:
	    movem.l (%sp)+, %d1-%d3
	    rts

	.if RASTAN_GAMEPLAY_HUD_SPRITES == 2
/* Build 0233 gameplay HUD projection.
 * The arcade score producer writes the P1 score/1UP setup records at 28..36,
 * but the translated gameplay sprite population can reuse part of that range.
 * Project the same packed-BCD P1 score into helper-owned records 0..8 only in
 * gameplay Mode 2, then let the normal object-table -> SAT path handle them.
 */
.Lpc090oj_mode2_project_p1_hud:
	    movem.l %d0-%d7/%a0-%a2, -(%sp)
	    lea     pc090oj_object_ram, %a0
	    movea.l #0x00FF011E, %a2
	    clr.w   %d5                         /* significant digit has appeared */

	    moveq   #0, %d1                     /* 100000s: high nibble FF011E */
	    move.b  (%a2), %d1
	    lsr.b   #4, %d1
	    andi.w  #0x000F, %d1
	    moveq   #0x08, %d4
	    bsr     .Lmode2_emit_digit

	    moveq   #0, %d1                     /* 10000s: low nibble FF011E */
	    move.b  (%a2), %d1
	    andi.w  #0x000F, %d1
	    moveq   #0x10, %d4
	    bsr     .Lmode2_emit_digit
	    subq.l  #1, %a2

	    moveq   #0, %d1                     /* 1000s: high nibble FF011D */
	    move.b  (%a2), %d1
	    lsr.b   #4, %d1
	    andi.w  #0x000F, %d1
	    moveq   #0x18, %d4
	    bsr     .Lmode2_emit_digit

	    moveq   #0, %d1                     /* 100s: low nibble FF011D */
	    move.b  (%a2), %d1
	    andi.w  #0x000F, %d1
	    moveq   #0x20, %d4
	    bsr     .Lmode2_emit_digit
	    subq.l  #1, %a2

	    moveq   #0, %d1                     /* 10s: high nibble FF011C */
	    move.b  (%a2), %d1
	    lsr.b   #4, %d1
	    andi.w  #0x000F, %d1
	    moveq   #0x28, %d4
	    bsr     .Lmode2_emit_digit

	    moveq   #0, %d1                     /* 1s: low nibble FF011C */
	    move.b  (%a2), %d1
	    andi.w  #0x000F, %d1
	    moveq   #0x30, %d4
	    bsr     .Lmode2_emit_digit

	    tst.w   %d5
	    bne.s   .Lmode2_emit_label
	    lea     pc090oj_object_ram + (4 * 8), %a1
	    move.w  #0x0010, 2(%a1)             /* zero score displays as 00 */
	    move.w  #0x0010, 10(%a1)

	.Lmode2_emit_label:
	    clr.w   (%a0)+                      /* record 6: '1' */
	    move.w  #0x0010, (%a0)+
	    move.w  #0x0039, (%a0)+
	    move.w  #0x0040, (%a0)+
	    clr.w   (%a0)+                      /* record 7: 'U' */
	    clr.w   (%a0)+
	    move.w  #0x0048, (%a0)+
	    move.w  #0x0028, (%a0)+
	    clr.w   (%a0)+                      /* record 8: 'P' */
	    clr.w   (%a0)+
	    move.w  #0x0046, (%a0)+
	    move.w  #0x0038, (%a0)+

	    movem.l (%sp)+, %d0-%d7/%a0-%a2
	    rts

.Lmode2_emit_digit:
	    clr.w   (%a0)+
	    move.w  #0x0010, %d6
	    tst.w   %d5
	    bne.s   .Lmode2_digit_visible
	    tst.w   %d1
	    bne.s   .Lmode2_digit_visible
	    move.w  #0x0110, %d6               /* hidden leading zero */
	    bra.s   .Lmode2_digit_store
	.Lmode2_digit_visible:
	    moveq   #1, %d5
	.Lmode2_digit_store:
	    move.w  %d6, (%a0)+
	    addi.w  #0x002A, %d1
	    move.w  %d1, (%a0)+
	    move.w  %d4, (%a0)+
	    rts
	.endif

	/* One ascending pass over the object table into the back shadow-SAT bank.  */
	pc090oj_native_emit_pass:
	    movem.l %d0-%d7/%a0-%a3, -(%sp)
	    lea     staged_sprite_sat, %a3
	    tst.w   pc090oj_sat_bank
	    beq.s   .Lnep_bank_ok
	    lea     staged_sprite_sat_b, %a3
	.Lnep_bank_ok:
	.if RASTAN_GAMEPLAY_HUD_SPRITES == 2
	    cmpi.b  #PC090OJ_SCENE_GAMEPLAY_ID, genesistan_current_scene_id
	    bne.s   .Lnep_no_mode2_p1_hud
	    bsr     .Lpc090oj_mode2_project_p1_hud
	.Lnep_no_mode2_p1_hud:
	.endif
	    lea     sprite_tile_resident_code, %a2
	    lea     pc090oj_cell_used, %a1     /* per-frame referenced-cell bitmap */
	    clr.l   (%a1)+
    clr.l   (%a1)+
    clr.l   (%a1)+
    clr.l   (%a1)+
    moveq   #0, %d5                    /* d5 = emitted count / cursor */
    moveq   #0, %d6                    /* d6 = record */
.Lnep_loop:
.if RASTAN_GAMEPLAY_HUD_SPRITES != 1
    cmpi.w  #46, %d6                   /* records 0..45 = arcade HUD family */
    bhs.s   .Lnep_not_hud
    cmpi.b  #PC090OJ_SCENE_GAMEPLAY_ID, genesistan_current_scene_id
    bne.s   .Lnep_not_hud
		.if RASTAN_GAMEPLAY_HUD_SPRITES == 2
		    /* Build 0233: keep only helper-owned gameplay P1 score records 0..8.
		     * Records 9..45 are reserved/overlapping arcade-HUD family rows. */
	    cmpi.w  #9, %d6
	    blo.s   .Lnep_not_hud
	.endif
	    bra     .Lnep_next
.Lnep_not_hud:
.endif
    move.w  %d5, -(%sp)                /* decode clobbers d5 (cursor) */
	    bsr     .Lpc090oj_decode_record    /* d6 -> d0 draw,d1 w0,d2 Y,d3 code,d4 X,d7 colbank */
	    move.w  (%sp)+, %d5
	    tst.w   %d0
	    beq     .Lnep_next
	.if RASTAN_GAMEPLAY_HUD_SPRITES == 2
		    /* Build 0232: gameplay score/1UP records keep arcade variable-width
		     * visibility, but use a separate white glyph residency variant. */
		    cmpi.b  #PC090OJ_SCENE_GAMEPLAY_ID, genesistan_current_scene_id
		    bne.s   .Lnep_no_hud_white
		    cmpi.w  #9, %d6
		    bhs.s   .Lnep_no_hud_white
	    cmpi.w  #0x002A, %d3
	    blo.s   .Lnep_hud_white_label_check
	    cmpi.w  #0x0034, %d3
	    blo.s   .Lnep_hud_white
	.Lnep_hud_white_label_check:
	    cmpi.w  #0x0039, %d3
	    beq.s   .Lnep_hud_white
	    cmpi.w  #0x0046, %d3
	    beq.s   .Lnep_hud_white
	    cmpi.w  #0x0048, %d3
	    bne.s   .Lnep_no_hud_white
	.Lnep_hud_white:
	    ori.w   #0x8000, %d3              /* residency tag only; VDP tile attrs unchanged */
	.Lnep_no_hud_white:
	.endif
	    /* Build 0222 code-keyed residency: 32 sets x 4 ways over cells 0..127.
	     * Per-frame REFERENCE PROTECTION: a cell used by any entry of the frame
     * being built can never be chosen as a victim, so no displayed sprite can
     * have its patterns stolen (the 0221 wrong-art/disappear mechanism).
     * EMIT-ON-MISS: an enqueued upload lands in VBlank BEFORE the SAT DMA, so
     * a missing code is emitted pointing at its newly assigned cell with an
     * optimistic tag -- residency misses are invisible.  Only queue overflow
     * or a fully-referenced set skips (bounded, counted). */
    move.w  %d3, %d0
    andi.w  #0x001F, %d0
    lsl.w   #3, %d0                    /* d0 = set*8 = way0 tag byte offset */
    cmp.w   0(%a2,%d0.w), %d3
    beq     .Lnep_hit
    addq.w  #2, %d0
    cmp.w   0(%a2,%d0.w), %d3
    beq     .Lnep_hit
    addq.w  #2, %d0
    cmp.w   0(%a2,%d0.w), %d3
    beq     .Lnep_hit
    addq.w  #2, %d0
    cmp.w   0(%a2,%d0.w), %d3
    beq     .Lnep_hit
    /* miss: pick the first way in the set whose cell is unreferenced */
    move.w  %d1, -(%sp)
    move.w  %d3, %d0
    andi.w  #0x001F, %d0
    lsl.w   #3, %d0
    moveq   #3, %d1
.Lnep_vloop:
    bsr     .Lnep_cell_free
    beq.s   .Lnep_take
    addq.w  #2, %d0
    dbra    %d1, .Lnep_vloop
    move.w  (%sp)+, %d1
    addq.w  #1, pc090oj_dropped_count  /* all 4 ways referenced this frame */
    bra     .Lnep_next
.Lnep_take:
    move.w  pc090oj_tile_dma_count, %d1
    cmpi.w  #12, %d1
    bhs.s   .Lnep_qfull
    lea     pc090oj_tile_dma_worklist, %a1
    lsl.w   #2, %d1
    adda.w  %d1, %a1
    move.w  %d0, %d1
    lsr.w   #1, %d1                    /* cell */
    move.w  %d1, (%a1)+
    move.w  %d3, (%a1)                 /* code */
    addq.w  #1, pc090oj_tile_dma_count
    move.w  %d3, 0(%a2,%d0.w)          /* optimistic tag: same-frame re-hits */
    move.w  (%sp)+, %d1
    bra     .Lnep_hit                  /* emit pointing at the enqueued cell */
.Lnep_qfull:
    move.w  (%sp)+, %d1
    addq.w  #1, pc090oj_dropped_count
    bra     .Lnep_next
/* d0 = tag byte offset; returns eq when the cell is NOT referenced this frame.
 * Clobbers a1/flags only. */
.Lnep_cell_free:
    move.w  %d0, -(%sp)
    lea     pc090oj_cell_used, %a1
    lsr.w   #4, %d0
    adda.w  %d0, %a1
    move.w  (%sp), %d0
    lsr.w   #1, %d0
    andi.w  #7, %d0
    btst    %d0, (%a1)
    movem.w (%sp)+, %d0                /* movem: restores d0 WITHOUT touching CCR */
    rts
.Lnep_hit:
    /* mark the cell referenced (protects it for the rest of this frame) */
    move.w  %d0, -(%sp)
    lea     pc090oj_cell_used, %a1
    lsr.w   #4, %d0
    adda.w  %d0, %a1
    move.w  (%sp), %d0
    lsr.w   #1, %d0
    andi.w  #7, %d0
    bset    %d0, (%a1)
    move.w  (%sp)+, %d0
.Lnep_res_ok:
    /* d0 = tag byte offset = cell*2 */
    move.w  %d0, -(%sp)                /* save cell*2 */
    /* word0: Y + bias */
    move.w  %d2, %d0
    andi.w  #0x01FF, %d0
    addi.w  #PC090OJ_SAT_Y_BIAS, %d0
    andi.w  #0x01FF, %d0
    move.w  %d0, (%a3)+
    /* word1: size 16x16 | link = cursor+1 (last patched after the pass) */
    move.w  %d5, %d0
    addq.w  #1, %d0
    andi.w  #0x007F, %d0
    ori.w   #0x0500, %d0
    move.w  %d0, (%a3)+
    /* word2: pri | flips | tile.  Palette bits are resolved at COMMIT time:
     * sprite_ctrl (colbank) is display-latch state the arcade sets AFTER its
     * producers run, so the mainline pass records each entry's bank nibble in
     * a parallel array and the VBlank fix-up applies the latched colbank. */
	    move.w  %d1, %d0
	    andi.w  #0x000F, %d0
	    lea     pc090oj_sat_nibble, %a1
	    move.b  %d0, 0(%a1,%d5.w)
	.if RASTAN_GAMEPLAY_HUD_SPRITES == 2
	    lea     pc090oj_sat_force_line, %a1
	    move.b  #0xFF, 0(%a1,%d5.w)
	    btst    #15, %d3
	    beq.s   .Lnep_no_force_line
	    move.b  #3, 0(%a1,%d5.w)          /* HUD white variant uses CRAM line 3 */
	.Lnep_no_force_line:
	.endif
	    moveq   #0, %d0
	    ori.w   #0x8000, %d0
    btst    #15, %d1                   /* post-flip vflip */
    beq.s   .Lnep_novf
    ori.w   #0x1000, %d0
.Lnep_novf:
    btst    #14, %d1                   /* post-flip hflip */
    beq.s   .Lnep_nohf
    ori.w   #0x0800, %d0
.Lnep_nohf:
    move.w  (%sp)+, %d2                /* cell*2 (Y no longer needed) */
    add.w   %d2, %d2                   /* cell*4 */
    addi.w  #SPRITE_TILE_BASE, %d2
    andi.w  #0x07FF, %d2
    or.w    %d2, %d0
    move.w  %d0, (%a3)+
    /* word3: X + bias */
    move.w  %d4, %d0
    andi.w  #0x01FF, %d0
    addi.w  #PC090OJ_SAT_X_BIAS, %d0
    andi.w  #0x01FF, %d0
    move.w  %d0, (%a3)+
    addq.w  #1, %d5
    cmpi.w  #NATIVE_SAT_MAX, %d5
    bhs.s   .Lnep_done_scan            /* first-80 in ascending arcade order */
.Lnep_next:
    addq.w  #1, %d6
    cmpi.w  #256, %d6
    blo     .Lnep_loop
.Lnep_done_scan:
    tst.w   %d5
    bne.s   .Lnep_have
    clr.w   (%a3)+                     /* zero sprites: hidden terminator */
    clr.w   (%a3)+
    clr.w   (%a3)+
    clr.w   (%a3)+
    bra.s   .Lnep_store
.Lnep_have:
    move.w  -6(%a3), %d0               /* last entry: link = 0 terminates */
    andi.w  #0xFF80, %d0
    move.w  %d0, -6(%a3)
.Lnep_store:
    move.w  %d5, pc090oj_emitted_count
    move.w  #1, pc090oj_sat_frame_ready
    move.w  #1, pc090oj_sat_dirty
    movem.l (%sp)+, %d0-%d7/%a0-%a3
    rts

/* Commit-time palette resolution: apply the DISPLAY-LATCHED colbank to every
 * emitted entry (<=80 iterations).  d7 = colbank from the current sprite_ctrl
 * shadow; per entry d1 = stored bank nibble -> .Lnative_palsel line. */
.Lnative_pal_fixup:
    movem.l %d0-%d7/%a0-%a3, -(%sp)
    move.w  pc090oj_emitted_count, %d6
    beq.s   .Lnpf_done
    lea     staged_sprite_sat, %a3
    tst.w   pc090oj_sat_front
    beq.s   .Lnpf_base_ok
    lea     staged_sprite_sat_b, %a3
	.Lnpf_base_ok:
	    lea     pc090oj_sat_nibble, %a2
	.if RASTAN_GAMEPLAY_HUD_SPRITES == 2
	    lea     pc090oj_sat_force_line, %a1
	.endif
	    move.w  pc090oj_sprite_ctrl_shadow, %d7
	    andi.w  #0x00E0, %d7
	    lsr.w   #1, %d7
	    moveq   #0, %d5
	.Lnpf_loop:
	    moveq   #0, %d1
	    move.b  0(%a2,%d5.w), %d1
	.if RASTAN_GAMEPLAY_HUD_SPRITES == 2
	    moveq   #0, %d0
	    move.b  0(%a1,%d5.w), %d0
	    cmpi.b  #0xFF, %d0
	    bne.s   .Lnpf_line_ready
	.endif
	    bsr     .Lnative_palsel            /* d1 nibble + d7 colbank -> d0 line */
	.Lnpf_line_ready:
	    lsl.w   #8, %d0
	    lsl.w   #5, %d0
    move.w  4(%a3), %d1
    andi.w  #0x9FFF, %d1               /* clear palette bits */
    or.w    %d0, %d1
    move.w  %d1, 4(%a3)
    adda.w  #8, %a3
    addq.w  #1, %d5
    cmp.w   %d6, %d5
    blo.s   .Lnpf_loop
.Lnpf_done:
    movem.l (%sp)+, %d0-%d7/%a0-%a3
    rts

/* VBlank entry (called by _vblank_service): frontend fallback pass only.    */
vdp_prepare_sprites:
    tst.w   pc090oj_sat_frame_ready
    bne.s   .Lvps_done
    bsr     pc090oj_native_emit_pass
.Lvps_done:
    rts

/* VBlank commit: pattern uploads, then publish+DMA the finished bank.       */
vdp_commit_sprites:
vdp_commit_sprites_vram:
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    bsr     .Lvcs_tile_dma
    tst.w   pc090oj_sat_frame_ready
    beq.s   .Lvcs_commit_done
    move.w  pc090oj_sat_bank, pc090oj_sat_front
    eori.w  #1, pc090oj_sat_bank
    clr.w   pc090oj_sat_frame_ready
    bsr     .Lnative_pal_fixup
    bsr     .Lvcs_sat_dma
    clr.w   pc090oj_sat_dirty
.Lvcs_commit_done:
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

.Lpc090oj_decode_record:
    move.w  %d6, %d0
    lsl.w   #3, %d0
    lea     pc090oj_object_ram, %a0
    adda.w  %d0, %a0
    move.w  (%a0), %d1
    move.w  2(%a0), %d2
    move.w  4(%a0), %d3
    move.w  6(%a0), %d4

    andi.w  #0x1FFF, %d3
    beq     .Ldecode_notdraw
    cmpi.w  #0x1000, %d3
    bhs     .Ldecode_notdraw
    move.w  %d3, %d5
    lsr.w   #3, %d5
    lea     pc090oj_blank_code_bitset, %a1
    move.b  0(%a1,%d5.w), %d5
    move.w  %d3, %d0
    andi.w  #0x0007, %d0
    btst    %d0, %d5
    bne     .Ldecode_notdraw

    andi.w  #0x01FF, %d2
    cmpi.w  #0x0140, %d2
    bls.s   .Ldecode_y_ok
    subi.w  #0x0200, %d2
.Ldecode_y_ok:
    andi.w  #0x01FF, %d4
    cmpi.w  #0x0140, %d4
    bls.s   .Ldecode_x_ok
    subi.w  #0x0200, %d4
.Ldecode_x_ok:
    move.w  pc090oj_ctrl_shadow, %d5
    btst    #0, %d5
    bne.s   .Ldecode_no_flip
    move.w  #PC090OJ_FLIP_X_TERM, %d5
    sub.w   %d4, %d5
    move.w  %d5, %d4
    move.w  #PC090OJ_FLIP_Y_TERM, %d5
    sub.w   %d2, %d5
    move.w  %d5, %d2
    eori.w  #0xC000, %d1
.Ldecode_no_flip:
    /* Arcade -> Genesis viewport origin: aligns sprites with the background
     * (which applies the matching bias in vdp_comm.s) and places the arcade top
     * margin above the Genesis viewport, where clipped records drop out. */
    addi.w  #PC090OJ_TO_GENESIS_X_OFFSET, %d4
    addi.w  #PC090OJ_TO_GENESIS_Y_OFFSET, %d2

    /* Opaque-geometry viewport clip.  A record is drawable only when at least
     * one opaque pixel of its post-flip pattern intersects the effective clip
     * rectangle; fully-clipped records return not-drawable, so they receive no
     * SAT slot, link entry, tile work, or scanline capacity.  d3 = code
     * (0..0x0FFF); box bytes = [min_row, max_row, min_col, max_col] (unflipped). */
    move.w  %d3, %d0
    andi.w  #0x0FFF, %d0
    lsl.w   #2, %d0
    lea     pc090oj_opaque_bbox, %a1
    adda.w  %d0, %a1
    /* vertical opaque span (post vertical-flip) vs [TOP, BOTTOM) */
    moveq   #0, %d0
    move.b  0(%a1), %d0                    /* min_row */
    moveq   #0, %d5
    move.b  1(%a1), %d5                    /* max_row */
    btst    #15, %d1                       /* vflip (post-flip word0 bit 15) */
    beq.s   .Ldecode_vrows_ok
    neg.w   %d0
    addi.w  #PC090OJ_PATTERN_MAX_ROW, %d0  /* MAX_ROW - min_row */
    neg.w   %d5
    addi.w  #PC090OJ_PATTERN_MAX_ROW, %d5  /* MAX_ROW - max_row */
    exg     %d0, %d5                       /* d0 = eff top row, d5 = eff bottom row */
.Ldecode_vrows_ok:
    add.w   %d2, %d0                       /* opaque top    (screen Y) */
    add.w   %d2, %d5                       /* opaque bottom (screen Y) */
    cmpi.w  #GENESIS_VIEWPORT_BOTTOM, %d0
    bge     .Ldecode_notdraw               /* opaque top at/below viewport bottom */
    cmpi.w  #GENESIS_VIEWPORT_TOP, %d5
    blt     .Ldecode_notdraw               /* opaque bottom above viewport top */
    /* horizontal opaque span (post horizontal-flip) vs [LEFT, RIGHT) */
    moveq   #0, %d0
    move.b  2(%a1), %d0                    /* min_col */
    moveq   #0, %d5
    move.b  3(%a1), %d5                    /* max_col */
    btst    #14, %d1                       /* hflip (post-flip word0 bit 14) */
    beq.s   .Ldecode_hcols_ok
    neg.w   %d0
    addi.w  #PC090OJ_PATTERN_MAX_COL, %d0  /* MAX_COL - min_col */
    neg.w   %d5
    addi.w  #PC090OJ_PATTERN_MAX_COL, %d5  /* MAX_COL - max_col */
    exg     %d0, %d5                       /* d0 = eff left col, d5 = eff right col */
.Ldecode_hcols_ok:
    add.w   %d4, %d0                       /* opaque left  (screen X) */
    add.w   %d4, %d5                       /* opaque right (screen X) */
    cmpi.w  #GENESIS_VIEWPORT_RIGHT, %d0
    bge     .Ldecode_notdraw               /* opaque left at/right of viewport right */
    cmpi.w  #GENESIS_VIEWPORT_LEFT, %d5
    blt     .Ldecode_notdraw               /* opaque right left of viewport left */
    andi.w  #0x0FFF, %d3
    move.w  pc090oj_sprite_ctrl_shadow, %d7
    andi.w  #0x00E0, %d7
    lsr.w   #1, %d7
    moveq   #1, %d0
    rts
.Ldecode_notdraw:
    moveq   #0, %d0
    rts

/* Generic bitmap scans (base-68000; a1=base, d5=total bits). */
/* First SET bit >= d0.  Returns d0 = bit or d5.  Clobbers d1-d3. */

/*
 * Precomputed tile-DMA worklist commit.  Bounded by pc090oj_tile_dma_count,
 * skips canceled entries (code 0xFFFF), updates slot residency only after the
 * DMA, and resets the reservation map + count at the end of the interval.
 */
.Lvcs_tile_dma:
    move.w  pc090oj_tile_dma_count, %d7
    beq     .Lvcs_tile_reset
    moveq   #0, %d5
.Lvcs_tile_loop:
    move.w  %d5, %d0
    lsl.w   #2, %d0
    lea     pc090oj_tile_dma_worklist, %a0
    adda.w  %d0, %a0
    move.w  (%a0), %d4                  /* slot */
    move.w  2(%a0), %d6                /* code (0xFFFF = canceled) */
    cmpi.w  #0xFFFF, %d6
    beq     .Lvcs_tile_next

	    move.w  %d6, %d0
	    andi.w  #0x0FFF, %d0
	.if RASTAN_GAMEPLAY_HUD_SPRITES == 2
	    btst    #15, %d6
	    beq.s   .Lvcs_tile_src_normal
	    move.w  %d0, %d3
	    subi.w  #0x002A, %d3
	    mulu.w  #128, %d3
	    lea     rastan_pc090oj_hud_white, %a1
	    adda.l  %d3, %a1
	    bra.s   .Lvcs_tile_src_ready
	.Lvcs_tile_src_normal:
	.endif
	    mulu.w  #128, %d0
	    lea     rastan_pc090oj, %a1
	    adda.l  %d0, %a1
	.Lvcs_tile_src_ready:
	    move.l  %a1, %d0
    lsr.l   #1, %d0
    movea.l #VDP_CTRL, %a3
    move.w  #0x9340, (%a3)
    move.w  #0x9400, (%a3)
    move.w  %d0, %d3
    andi.w  #0x00FF, %d3
    ori.w   #0x9500, %d3
    move.w  %d3, (%a3)
    move.l  %d0, %d3
    lsr.l   #8, %d3
    andi.w  #0x00FF, %d3
    ori.w   #0x9600, %d3
    move.w  %d3, (%a3)
    move.l  %d0, %d3
    lsr.l   #8, %d3
    lsr.l   #8, %d3
    andi.w  #0x007F, %d3
    ori.w   #0x9700, %d3
    move.w  %d3, (%a3)
    move.w  %d4, %d0
    lsl.w   #2, %d0
    addi.w  #SPRITE_TILE_BASE, %d0
    lsl.l   #5, %d0
    move.l  %d0, %d1
    andi.l  #0x00003FFF, %d1
    swap    %d1
    move.l  %d0, %d2
    lsr.l   #8, %d2
    lsr.l   #6, %d2
    andi.l  #0x00000003, %d2
    ori.l   #0x40000080, %d1
    or.l    %d2, %d1
    move.l  %d1, (%a3)
    move.w  %d4, %d0
    add.w   %d0, %d0
    lea     sprite_tile_resident_code, %a1
    move.w  %d6, 0(%a1,%d0.w)
.Lvcs_tile_next:
    addq.w  #1, %d5
    cmp.w   %d7, %d5
    blo     .Lvcs_tile_loop
.Lvcs_tile_reset:
    /* Reset only the slots actually reserved this interval (d7 = count, still
     * live), so a stable no-work frame (count 0) does zero reset work. */
    tst.w   %d7
    beq.s   .Lvcs_tile_reset_done
    moveq   #0, %d5
.Lvcs_tile_reset_loop:
    move.w  %d5, %d0
    lsl.w   #2, %d0
    lea     pc090oj_tile_dma_worklist, %a0
    adda.w  %d0, %a0
    moveq   #0, %d0
    move.w  (%a0), %d0                  /* reserved slot for this entry */
    lea     worklist_entry_for_slot, %a1
    move.b  #0xFF, 0(%a1,%d0.w)
    addq.w  #1, %d5
    cmp.w   %d7, %d5
    blo.s   .Lvcs_tile_reset_loop
.Lvcs_tile_reset_done:
    clr.w   pc090oj_tile_dma_count
    rts

/* SAT DMA: length = max(highest_used+1, 1) * 4 words, clamped to 80 slots. */
.Lvcs_sat_dma:
    movea.l #VDP_CTRL, %a3
    move.w  #80, %d0                   /* constant full-table DMA (640 B) */
    lsl.w   #2, %d0

    move.w  %d0, %d1
    andi.w  #0x00FF, %d1
    ori.w   #0x9300, %d1
    move.w  %d1, (%a3)

    move.w  %d0, %d1
    lsr.w   #8, %d1
    andi.w  #0x00FF, %d1
    ori.w   #0x9400, %d1
    move.w  %d1, (%a3)

    move.l  #staged_sprite_sat, %d0
    tst.w   pc090oj_sat_front
    beq.s   .Lsat_src_ok
    move.l  #staged_sprite_sat_b, %d0
.Lsat_src_ok:
    lsr.l   #1, %d0

    move.w  %d0, %d1
    andi.w  #0x00FF, %d1
    ori.w   #0x9500, %d1
    move.w  %d1, (%a3)

    move.l  %d0, %d1
    lsr.l   #8, %d1
    andi.w  #0x00FF, %d1
    ori.w   #0x9600, %d1
    move.w  %d1, (%a3)

    move.l  %d0, %d1
    lsr.l   #8, %d1
    lsr.l   #8, %d1
    andi.w  #0x007F, %d1
    ori.w   #0x9700, %d1
    move.w  %d1, (%a3)

    move.l  #0x0000F800, %d0
    move.l  %d0, %d1
    andi.l  #0x00003FFF, %d1
    swap    %d1
    move.l  %d0, %d2
    lsr.l   #8, %d2
    lsr.l   #6, %d2
    andi.l  #0x00000003, %d2
    ori.l   #0x40000080, %d1
    or.l    %d2, %d1
    move.l  %d1, (%a3)
    rts

/* ------------------------------------------------------------------------- */
/* VRAM DMA self-test                                                        */
/* ------------------------------------------------------------------------- */

genesistan_pc090oj_dma_self_test:
    movem.l %d0-%d7/%a0-%a6, -(%sp)

    /* Stack buffer (128 bytes) */
    lea     -128(%sp), %sp
    movea.l %sp, %a6

    /* DMA source: rastan_pc090oj + 0x80, len 64 words, dest VRAM 0x8000 */
    lea     rastan_pc090oj+0x80, %a1
    move.l  %a1, %d0
    lsr.l   #1, %d0

    movea.l #VDP_CTRL, %a3
    move.w  #0x9340, (%a3)
    move.w  #0x9400, (%a3)

    move.w  %d0, %d1
    andi.w  #0x00FF, %d1
    ori.w   #0x9500, %d1
    move.w  %d1, (%a3)

    move.l  %d0, %d1
    lsr.l   #8, %d1
    andi.w  #0x00FF, %d1
    ori.w   #0x9600, %d1
    move.w  %d1, (%a3)

    move.l  %d0, %d1
    lsr.l   #8, %d1
    lsr.l   #8, %d1
    andi.w  #0x007F, %d1
    ori.w   #0x9700, %d1
    move.w  %d1, (%a3)

    move.l  #0x00008000, %d0
    move.l  %d0, %d1
    andi.l  #0x00003FFF, %d1
    swap    %d1
    move.l  %d0, %d2
    lsr.l   #8, %d2
    lsr.l   #6, %d2
    andi.l  #0x00000003, %d2
    ori.l   #0x40000080, %d1
    or.l    %d2, %d1
    move.l  %d1, (%a3)

    /* Read back VRAM 0x8000..0x807F into stack buffer */
    move.l  #0x00008000, %d0
    move.l  %d0, %d1
    andi.l  #0x00003FFF, %d1
    swap    %d1
    move.l  %d0, %d2
    lsr.l   #8, %d2
    lsr.l   #6, %d2
    andi.l  #0x00000003, %d2
    or.l    %d2, %d1                 /* VRAM read command (no write/dma bits) */
    move.l  %d1, (%a3)

    movea.l #VDP_DATA, %a4
    move.w  #(64 - 1), %d0
.Lpc090oj_dma_read_loop:
    move.w  (%a4), (%a6)+
    dbra    %d0, .Lpc090oj_dma_read_loop

    /* Compare 64 words */
    lea     rastan_pc090oj+0x80, %a0
    movea.l %sp, %a1
    moveq   #0, %d6
    move.w  #(64 - 1), %d0
.Lpc090oj_dma_cmp_loop:
    move.w  (%a0)+, %d1
    move.w  (%a1)+, %d2
    cmp.w   %d1, %d2
    bne.s   .Lpc090oj_dma_fail
    addq.w  #1, %d6
    dbra    %d0, .Lpc090oj_dma_cmp_loop

    lea     128(%sp), %sp
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

.Lpc090oj_dma_fail:
    move.w  %d6, pc090oj_dma_test_mismatch_offset
    move.w  %d1, pc090oj_dma_test_expected_word
    move.w  %d2, pc090oj_dma_test_actual_word

    /* copy full 128-byte snapshot */
    movea.l %sp, %a0
    lea     pc090oj_dma_test_actual_buffer, %a1
    move.w  #(128/2 - 1), %d0
.Lpc090oj_dma_copy_buf:
    move.w  (%a0)+, (%a1)+
    dbra    %d0, .Lpc090oj_dma_copy_buf

    move.w  #0x6F0E, pc090oj_dma_test_fired_flag

.Lpc090oj_dma_test_halt:
    move.b  pc090oj_dma_test_heartbeat, %d0
    addq.b  #1, %d0
    move.b  %d0, pc090oj_dma_test_heartbeat
    bra     .Lpc090oj_dma_test_halt

/* ------------------------------------------------------------------------- */
/* BSS                                                                        */
/* ------------------------------------------------------------------------- */

    .section .bss
    .align 2

/* N1 shadow SAT double buffer (final Genesis SAT format, link-ordered). */
staged_sprite_sat:
    .space (80 * 8)
staged_sprite_sat_b:
    .space (80 * 8)
pc090oj_sat_bank:
    .word 0
pc090oj_sat_front:
    .word 0
pc090oj_sat_frame_ready:
    .word 0
pc090oj_sat_nibble:
	    .space 80
pc090oj_sat_force_line:
	    .space 80
	    .align 2
/* Per-frame referenced-cell bitmap (128 bits). */
pc090oj_cell_used:
    .space 16
/* Code-keyed residency tags: 64 sets x 2 ways = 128 cells (tiles 1024..1535). */
sprite_tile_resident_code:
    .space (128 * 2)
/* Bounded VBlank pattern-upload queue: 12 x {word cell, word code}. */
pc090oj_tile_dma_worklist:
    .space (12 * 4)
pc090oj_tile_dma_count:
    .word 0
/* The arcade program's persistent slot-addressed object store (256 rows).
 * This is arcade state (incremental producers update rows in place), not a
 * chip mirror: nothing scans, diffs, or reverse-converts it except the one
 * per-frame native emit pass. Fixed 256 rows: no mirror-size configuration. */
pc090oj_object_ram:
    .space (256 * 8)
pc090oj_ctrl_shadow:
    .word 0
pc090oj_sprite_ctrl_shadow:
    .word 0
pc090oj_mirror_dirty:
    .word 0
pc090oj_candidate_count:
    .word 0
pc090oj_decoded_count:
    .word 0
pc090oj_code_zero_skipped_count:
    .word 0
pc090oj_blank_skipped_count:
    .word 0
pc090oj_unmapped_skipped_count:
    .word 0
pc090oj_offscreen_skipped_count:
    .word 0
pc090oj_hud_suppressed_count:
    .word 0
pc090oj_drawable_count:
    .word 0
pc090oj_emitted_count:
    .word 0
pc090oj_dropped_count:
    .word 0
pc090oj_scan_colbank:
    .word 0
pc090oj_scan_active:
    .word 0
pc090oj_producer_oob_count:
    .word 0
pc090oj_producer_write_count:
    .word 0
pc090oj_represented_count:
    .word 0
pc090oj_sat_dirty:
    .word 0
pc090oj_bootstrap_pending:
    .word 0
.Lscratch_rec:
    .word 0
.Lrecord46_rec:
    .word 0
.Lrecord46_count:
    .word 0
    .align 2
.Lrecord46_scratch:
    .space 8
/* Audit-guard + DMA self-test diagnostics (retained consumers). */
audit_guard_caller_pc:
    .long 0
audit_guard_register_snapshot:
    .space (16 * 4)
audit_guard_vcount:
    .word 0
audit_guard_fired_flag:
    .word 0
audit_guard_heartbeat:
    .word 0
    .align 2

/* Legacy exported stubs (symbols retained; no runtime consumers). */
staged_sprite_dirty:
    .long 0
staged_sprite_active_count:
    .word 0
staged_sprite_descriptor_table:
pc090oj_candidate_bitset:
record_to_slot:
represented_records:
waiting_records:
used_sat_slots:
worklist_entry_for_slot:
    .space 4
    .align 2

    .section .bss.patcher
    .balign 2
pc090oj_dma_test_fired_flag:
    .word 0
pc090oj_dma_test_mismatch_offset:
    .word 0
pc090oj_dma_test_expected_word:
    .word 0
pc090oj_dma_test_actual_word:
    .word 0
pc090oj_dma_test_actual_buffer:
    .space 128
pc090oj_dma_test_heartbeat:
    .byte 0
